DECLARE @v_NullKeyCount   INT;
DECLARE @v_InvalidStatus  INT;
DECLARE @v_UnknownCharger INT;

SELECT @v_NullKeyCount = COUNT(*)
FROM dbo.raw_ev_telemetry
WHERE CAST(timestamp AS DATE) = '@{pipeline().parameters.pipeline_date}'
AND (charger_id IS NULL OR timestamp IS NULL OR state IS NULL OR city IS NULL);

SELECT @v_InvalidStatus = COUNT(*)
FROM dbo.raw_ev_telemetry
WHERE CAST(timestamp AS DATE) = '@{pipeline().parameters.pipeline_date}'
AND status NOT IN ('Available', 'Charging', 'Faulted');

SELECT @v_UnknownCharger = COUNT(*)
FROM dbo.raw_ev_telemetry
WHERE CAST(timestamp AS DATE) = '@{pipeline().parameters.pipeline_date}'
AND charger_id NOT LIKE 'CH[_]%[_]%';

INSERT INTO dbo.dq_validation_results (PipelineName, RunID, TableName, CheckName, Status, FailedRowCount, ExecutionTime)
VALUES
('@{pipeline().Pipeline}','@{pipeline().RunId}','raw_ev_telemetry','NULL Key Fields',           CASE WHEN @v_NullKeyCount   = 0 THEN 'Passed' ELSE 'Warning' END, @v_NullKeyCount,   GETUTCDATE()),
('@{pipeline().Pipeline}','@{pipeline().RunId}','raw_ev_telemetry','Invalid Status Values',     CASE WHEN @v_InvalidStatus  = 0 THEN 'Passed' ELSE 'Warning' END, @v_InvalidStatus,  GETUTCDATE()),
('@{pipeline().Pipeline}','@{pipeline().RunId}','raw_ev_telemetry','Unknown Charger ID Format', CASE WHEN @v_UnknownCharger = 0 THEN 'Passed' ELSE 'Warning' END, @v_UnknownCharger, GETUTCDATE());

DECLARE @RowCount INT;

SELECT @RowCount = COUNT(*) FROM dbo.raw_ev_telemetry
WHERE CAST(timestamp AS DATE) = '@{pipeline().parameters.pipeline_date}';

INSERT INTO dbo.dq_validation_results (PipelineName, RunID, TableName, CheckName, Status, FailedRowCount, ExecutionTime)
VALUES ('@{pipeline().Pipeline}','@{pipeline().RunId}','raw_ev_telemetry','Row Count Availability Check',
    CASE WHEN @RowCount > 0 THEN 'Passed' ELSE 'Warning' END, @RowCount, GETUTCDATE());

DECLARE @DuplicateCount INT;

SELECT @DuplicateCount = COUNT(*) FROM (
    SELECT charger_id, timestamp, COUNT(*) AS cnt
    FROM dbo.raw_ev_telemetry
    WHERE CAST(timestamp AS DATE) = '@{pipeline().parameters.pipeline_date}'
    GROUP BY charger_id, timestamp
    HAVING COUNT(*) > 1
) AS dups;

INSERT INTO dbo.dq_validation_results (PipelineName, RunID, TableName, CheckName, Status, FailedRowCount, ExecutionTime)
VALUES ('@{pipeline().Pipeline}','@{pipeline().RunId}','raw_ev_telemetry','Duplicate Records',
    CASE WHEN @DuplicateCount = 0 THEN 'Passed' ELSE 'Warning' END, @DuplicateCount, GETUTCDATE());

DECLARE @TotalRows       INT;
DECLARE @BillingNullRate DECIMAL(5,2);
DECLARE @ThermalNullRate DECIMAL(5,2);
DECLARE @AllPhaseNull    INT;
DECLARE @UserNullRate    DECIMAL(5,2);
DECLARE @BMSNullRate     DECIMAL(5,2);

SELECT @TotalRows = COUNT(*) FROM dbo.raw_ev_telemetry
WHERE CAST(timestamp AS DATE) = '@{pipeline().parameters.pipeline_date}';

SELECT @BillingNullRate = CAST(COUNT(CASE WHEN electricity_cost_inr IS NULL THEN 1 END) AS DECIMAL) / NULLIF(@TotalRows,0) * 100
FROM dbo.raw_ev_telemetry WHERE CAST(timestamp AS DATE) = '@{pipeline().parameters.pipeline_date}';

SELECT @ThermalNullRate = CAST(COUNT(CASE WHEN connector_temp_c IS NULL THEN 1 END) AS DECIMAL) / NULLIF(@TotalRows,0) * 100
FROM dbo.raw_ev_telemetry WHERE CAST(timestamp AS DATE) = '@{pipeline().parameters.pipeline_date}';

SELECT @AllPhaseNull = COUNT(*) FROM dbo.raw_ev_telemetry
WHERE CAST(timestamp AS DATE) = '@{pipeline().parameters.pipeline_date}'
AND current_phase_a_a IS NULL AND current_phase_b_a IS NULL AND current_phase_c_a IS NULL;

SELECT @UserNullRate = CAST(COUNT(CASE WHEN user_id IS NULL THEN 1 END) AS DECIMAL) / NULLIF(COUNT(*),0) * 100
FROM dbo.raw_ev_telemetry WHERE CAST(timestamp AS DATE) = '@{pipeline().parameters.pipeline_date}' AND status = 'Charging';

SELECT @BMSNullRate = CAST(COUNT(CASE WHEN initial_soc_pct IS NULL AND user_id IS NOT NULL THEN 1 END) AS DECIMAL) / NULLIF(COUNT(CASE WHEN user_id IS NOT NULL THEN 1 END),0) * 100
FROM dbo.raw_ev_telemetry WHERE CAST(timestamp AS DATE) = '@{pipeline().parameters.pipeline_date}';

INSERT INTO dbo.dq_validation_results (PipelineName, RunID, TableName, CheckName, Status, FailedRowCount, ExecutionTime)
VALUES
('@{pipeline().Pipeline}','@{pipeline().RunId}','raw_ev_telemetry','Billing NULL Rate',          CASE WHEN @BillingNullRate <= 25 THEN 'Passed' ELSE 'Warning' END, CAST(@BillingNullRate AS INT), GETUTCDATE()),
('@{pipeline().Pipeline}','@{pipeline().RunId}','raw_ev_telemetry','Thermal Sensor NULL Rate',   CASE WHEN @ThermalNullRate <= 15 THEN 'Passed' ELSE 'Warning' END, CAST(@ThermalNullRate AS INT), GETUTCDATE()),
('@{pipeline().Pipeline}','@{pipeline().RunId}','raw_ev_telemetry','All Phase Current NULL',     CASE WHEN @AllPhaseNull = 0     THEN 'Passed' ELSE 'Warning'  END, @AllPhaseNull,                GETUTCDATE()),
('@{pipeline().Pipeline}','@{pipeline().RunId}','raw_ev_telemetry','User ID NULL During Charge', CASE WHEN @UserNullRate <= 15   THEN 'Passed' ELSE 'Warning'  END, CAST(@UserNullRate AS INT),    GETUTCDATE()),
('@{pipeline().Pipeline}','@{pipeline().RunId}','raw_ev_telemetry','BMS SOC NULL Rate',          CASE WHEN @BMSNullRate <= 12    THEN 'Passed' ELSE 'Warning'  END, CAST(@BMSNullRate AS INT),     GETUTCDATE());

DECLARE @VoltageOutliers INT;
DECLARE @UptimeOutliers  INT;
DECLARE @NegativeRevenue INT;

SELECT @VoltageOutliers = COUNT(*) FROM dbo.raw_ev_telemetry
WHERE CAST(timestamp AS DATE) = '@{pipeline().parameters.pipeline_date}'
AND (voltage_phase_a_v < 300 OR voltage_phase_a_v > 450
  OR voltage_phase_b_v < 300 OR voltage_phase_b_v > 450
  OR voltage_phase_c_v < 300 OR voltage_phase_c_v > 450);

SELECT @UptimeOutliers = COUNT(*) FROM dbo.raw_ev_telemetry
WHERE CAST(timestamp AS DATE) = '@{pipeline().parameters.pipeline_date}'
AND (uptime_pct < 0 OR uptime_pct > 100);

SELECT @NegativeRevenue = COUNT(*) FROM dbo.raw_ev_telemetry
WHERE CAST(timestamp AS DATE) = '@{pipeline().parameters.pipeline_date}'
AND (session_revenue_inr < 0 OR energy_delivered_kwh < 0);

INSERT INTO dbo.dq_validation_results (PipelineName, RunID, TableName, CheckName, Status, FailedRowCount, ExecutionTime)
VALUES
('@{pipeline().Pipeline}','@{pipeline().RunId}','raw_ev_telemetry','Voltage Out of Range',    CASE WHEN @VoltageOutliers = 0 THEN 'Passed' ELSE 'Warning' END, @VoltageOutliers, GETUTCDATE()),
('@{pipeline().Pipeline}','@{pipeline().RunId}','raw_ev_telemetry','Uptime Out of Range',     CASE WHEN @UptimeOutliers  = 0 THEN 'Passed' ELSE 'Warning' END, @UptimeOutliers,  GETUTCDATE()),
('@{pipeline().Pipeline}','@{pipeline().RunId}','raw_ev_telemetry','Negative Revenue/Energy', CASE WHEN @NegativeRevenue = 0 THEN 'Passed' ELSE 'Warning' END, @NegativeRevenue, GETUTCDATE());

DECLARE @FaultedNoCode    INT;
DECLARE @ChargingNoEnergy INT;

SELECT @FaultedNoCode = COUNT(*) FROM dbo.raw_ev_telemetry
WHERE CAST(timestamp AS DATE) = '@{pipeline().parameters.pipeline_date}'
AND status = 'Faulted' AND (error_code IS NULL OR error_code = 'None');

SELECT @ChargingNoEnergy = COUNT(*) FROM dbo.raw_ev_telemetry
WHERE CAST(timestamp AS DATE) = '@{pipeline().parameters.pipeline_date}'
AND status = 'Charging' AND energy_delivered_kwh < 0;

INSERT INTO dbo.dq_validation_results (PipelineName, RunID, TableName, CheckName, Status, FailedRowCount, ExecutionTime)
VALUES
('@{pipeline().Pipeline}','@{pipeline().RunId}','raw_ev_telemetry','Faulted Row Missing Error Code', CASE WHEN @FaultedNoCode    = 0 THEN 'Passed' ELSE 'Warning' END, @FaultedNoCode,    GETUTCDATE()),
('@{pipeline().Pipeline}','@{pipeline().RunId}','raw_ev_telemetry','Charging Row Negative Energy',   CASE WHEN @ChargingNoEnergy = 0 THEN 'Passed' ELSE 'Warning'  END, @ChargingNoEnergy, GETUTCDATE());
